    # Constants
    DENSITY_PLA = 1.24 / 1000  # g/mm3
    E_PLA = 3500                # MPa (N/mm2)
    FORCE_F = 50.0              # N
    LOAD_X = 40.0               # mm

    def clean(val):
        if isinstance(val, (np.bool_, bool)):
            return bool(val)
        if isinstance(val, (np.integer, int)):
