        if isinstance(val, (np.ndarray, list)):
            return [clean(x) for x in val]
        if isinstance(val, dict):
            return {k: clean(v) for k, v in val.items()}
        return val

    # R1: One single, valid solid
    try:
        n_solids = len(shape.Solids())
